select periode,tiers,fac,agence,categ,sum(remise_except) remise_except from ( select a.invdat_0 periode,a.bpcinv_0 tiers,a.num_0 fac,decode(substr(a.bpcinv_0,1,1),'X','C','Y','C','Z','C',substr(a.bpcinv_0,1,1)) agence,substr(a.bpcinv_0,2,1) categ, sum(b.dtanot_0)*-1 remise_except from sinvoicev a, svcrfoot b where  a.num_0=b.vcrnum_0 and a.invdat_0 between '01/01/2018' and  '31/12/2026' and  a.invdtaamt_1 <> 0 and a.sivtyp_0 in ('FAC','FCP') group by a.invdat_0 ,a.bpcinv_0 ,a.num_0,decode(substr(a.bpcinv_0,1,1),'X','C','Y','C','Z','C',substr(a.bpcinv_0,1,1)) ,substr(a.bpcinv_0,2,1) union select a.invdat_0 periode,a.bpcinv_0 tiers,a.num_0 fac,decode(substr(a.bpcinv_0,1,1),'X','C','Y','C','Z','C',substr(a.bpcinv_0,1,1)) agence,substr(a.bpcinv_0,2,1) categ, sum(b.dtanot_0) remise_except from sinvoicev a, svcrfoot b where  a.num_0=b.vcrnum_0 and a.invdat_0 between '01/01/2018' and  '31/12/2026' and  a.invdtaamt_1 <> 0 and a.sivtyp_0 in ('AVO','AVP') group by a.invdat_0 ,a.bpcinv_0 ,a.num_0,decode(substr(a.bpcinv_0,1,1),'X','C','Y','C','Z','C',substr(a.bpcinv_0,1,1)) ,substr(a.bpcinv_0,2,1) ) group by periode,tiers,fac,agence,categ
